from author_csharp_v2 import *

unit(115,
"SOLID مجموعهٔ پرسش‌های طراحی است،نه دستور ساخت interface برای هر کلاس. SRP یک دلیل مرتبط برای تغییر،OCP امکان گسترش متناسب،LSP حفظ قرارداد رفتاری زیرنوع،ISP قرارداد کوچک مصرف‌کننده و DIP وابستگی سیاست به قرارداد مناسب را هدف می‌گیرند. composition اغلب از inheritance نامتناسب ساده‌تر است. cohesion رفتار مرتبط را کنار هم و coupling وابستگی تغییر را نشان می‌دهد. refactoring باید رفتار را با تست محافظ حفظ کند؛ اصلاح نقض قرارداد ممکن است تغییر رفتار عمدی و مستند بخواهد. YAGNI تعمیم بی‌مصرف را کنار می‌گذارد،نه validation یا تست لازم را. کوچک‌ترین تغییر کامل،خروجی قابل نگهداری‌تری می‌دهد.",
'Console.WriteLine(new PriceService(new FixedRate()).Total(4));\ninterface IRate {int Apply(int n);}\nclass FixedRate:IRate {public int Apply(int n)=>n*2;}\nclass PriceService(IRate rate) {public int Total(int n)=>rate.Apply(n);}', '8',
("اگر فرزند پیش‌شرط پایه را سخت‌تر کند و مصرف‌کنندهٔ معتبر پایه را رد کند،کدام اصل در خطر است؟", "LSP و قرارداد جایگزینی", "صرفاً نام namespace", "همیشه نیاز به microservice", "زیرنوع باید انتظارات رفتاری قرارداد پایه را نگه دارد؛ inheritance فقط اشتراک شکل نیست."),
repair("ترمیم قرارداد جایگزینی", "پایه قیمت صفر را معتبر می‌داند؛ فرزند باید همان دامنه را حفظ کند.", ["if(price<=0) throw", "if(price<0) throw", "همهٔ قیمت‌ها را قبول کن"], [0], ["صفر پذیرفته", "منفی رد", "مثبت پذیرفته"], [([0],[False,True,True]),([1],[True,True,True]),([2],[True,False,True])]),
"یک وابستگی concrete در منطق را با قرارداد مصرف‌کننده جایگزین کن. نقض دامنهٔ ورودی در فرزند را با تست صفر آشکار و با کمترین تغییر اصلاح کن؛ لایهٔ اضافی بدون مصرف نساز.",
'Policy policy=new Vip();foreach(decimal price in new[]{0m,10m}) Console.WriteLine(policy.Apply(price));\nclass Policy {public virtual decimal Apply(decimal price){if(price<0)throw new ArgumentOutOfRangeException(nameof(price));return price;}}\nclass Vip:Policy {public override decimal Apply(decimal price)=>base.Apply(price)*0.9m;}',
"صفر و 9.0 یا معادل عددی چاپ شود. تست منفی حفظ و مصرف‌کنندهٔ پایه با Vip همچنان معتبر باشد؛ وابستگی‌ها فقط تا نیاز واقعی جدا شوند.")

unit(116,
"Factory Method نقطهٔ ساخت یک محصول را قابل تغییر می‌کند و Abstract Factory خانوادهٔ سازگار محصولات را می‌سازد. Builder ساخت مرحله‌ای با پیکربندی‌های متعدد را از نمایش نهایی جدا می‌کند؛ برای دو پارامتر ساده ممکن است سازنده کافی باشد. Prototype کپی از نمونهٔ موجود است و عمق کپی باید روشن باشد. Singleton یک نمونهٔ مشترک می‌خواهد،اما global mutable state و lifetime پنهان می‌تواند تست و همزمانی را سخت کند. Lazy<T> ساخت دیرهنگام با policy thread safety مشخص می‌دهد؛ cache خطا و reentrancy باید فهمیده شود. DI می‌تواند عمر singleton را بدون الگوی static دستی مدیریت کند. انتخاب الگو باید از مسئلهٔ ساخت بیاید،نه فهرست نام‌ها.",
'int calls=0;var lazy=new Lazy<int>(()=>{calls++;return 7;});\nConsole.WriteLine(lazy.Value);Console.WriteLine(lazy.Value);Console.WriteLine(calls);', '7\n7\n1',
("برای ساخت سادهٔ یک نوع با دو مقدار روشن،اول چه گزینه‌ای را می‌سنجی؟", "سازندهٔ مستقیم با validation", "Builder عمومی پیچیده برای آیندهٔ نامعلوم", "Singleton global برای هر داده", "الگو زمانی ارزش دارد که مسئلهٔ واقعی ساخت را حل کند؛ سازندهٔ کوچک اغلب کافی است."),
concept("کشف روش ساخت", "هدف پنهان یک روش ساخت مرحله‌ای است. از ویژگی‌های حدس‌ها برای کشف استفاده کن.", ["Factory Method","Builder","Prototype","Singleton"], ["قصد اصلی","مبنای ساخت"], [["تعویض سازندهٔ محصول","قرارداد factory"],["ساخت مرحله‌ای","گام‌های تنظیم"],["کپی نمونه","شیء موجود"],["نمونهٔ مشترک","عمر مشترک"]], 1),
"برای دو فرمت خروجی factory کوچک بساز؛ برای تنظیم ساده از سازنده استفاده کن و توضیح بده چرا Builder لازم نیست. Lazy<T> را برای ساخت یک منبع fake و policy مناسب تست کن.",
'Console.WriteLine(Create("text").Write(3));Console.WriteLine(Create("csv").Write(3));\nstatic IWriter Create(string format)=>format switch {"text"=>new TextWriter(),"csv"=>new CsvWriter(),_=>throw new ArgumentException("format")};\ninterface IWriter {string Write(int n);}\nclass TextWriter:IWriter {public string Write(int n)=>"Value="+n;}\nclass CsvWriter:IWriter {public string Write(int n)=>"value,"+n;}',
"Value=3 و value,3 چاپ شود؛ فرمت ناشناخته رد شود. ساخت منبع lazy در تست مستقل یک بار باشد؛ مالکیت آن روشن بماند.")

unit(117,
"Adapter قرارداد موجود را به قرارداد مورد نیاز مصرف‌کننده تبدیل می‌کند؛ Bridge دو محور تغییر را جدا نگه می‌دارد. Composite جزء و مجموعه را با قرارداد مشترک برای ساختار درختی می‌بیند. Decorator رفتار را دور همان قرارداد می‌پیچد و Facade رابط ساده برای زیرسامانهٔ پیچیده می‌دهد. Flyweight دادهٔ مشترک ثابت را با context بیرونی از وضعیت متغیر جدا می‌کند؛ اشتراک mutable بدون قرارداد خطرناک است. Proxy دسترسی،عمر یا مکان اجرای سرویس را نمایندگی می‌کند و ممکن است هزینهٔ پنهان داشته باشد. افزودن لایهٔ delegation به‌تنهایی ارزش نیست؛ consumer،هزینه و مالکیت باید روشن باشند.",
'IReader reader=new Prefix(new Raw());Console.WriteLine(reader.Read());\ninterface IReader {string Read();}\nclass Raw:IReader {public string Read()=>"data";}\nclass Prefix(IReader inner):IReader {public string Read()=>"prefix:"+inner.Read();}', 'prefix:data',
("برای سازگارکردن API قدیمی با قرارداد مصرف‌کنندهٔ جدید چه الگو مناسب است؟", "Adapter", "Singleton الزاماً", "تغییر همهٔ مصرف‌کننده‌ها بدون نیاز", "Adapter شکل قرارداد را تبدیل می‌کند؛ Decorator بیشتر رفتار را با حفظ همان قرارداد می‌افزاید."),
slots("نام الگو از مسئله", "هر نیاز را به الگوی ساختاری مناسب وصل کن.", ["تبدیل قرارداد قدیمی", "افزودن log با همان interface", "نمای سادهٔ زیرسامانه", "جزء و درخت هم‌قرارداد", "دو محور مستقل تغییر", "اشتراک دادهٔ ثابت", "نمای کنترل دسترسی"], ["Adapter","Decorator","Facade","Composite","Bridge","Flyweight","Proxy"], [0,1,2,3,4,5,6]),
"adapter برای خوانندهٔ قدیمی و decorator شمارندهٔ فراخوانی بساز. مصرف‌کننده فقط IReader ببیند و بدون تغییر کار کند. مالکیت inner در Dispose در صورت نیاز صریح باشد.",
'var counted=new Counted(new Adapter(new Legacy()));Console.WriteLine(counted.Read());Console.WriteLine(counted.Calls);\ninterface IReader {string Read();}\nclass Legacy {public string Fetch()=>"old";}\nclass Adapter(Legacy legacy):IReader {public string Read()=>legacy.Fetch();}\nclass Counted(IReader inner):IReader {public int Calls {get;private set;}public string Read(){Calls++;return inner.Read();}}',
"old و 1 چاپ شود. adapter قرارداد را تبدیل و decorator رفتار را با همان interface اضافه کند؛ تست شکست inner و عدم بلعیدن خطا هم باشد.")

unit(118,
"Strategy رفتار قابل جایگزین،Observer اعلان به مشترک،Command درخواست به‌شکل شیء و Chain of Responsibility عبور درخواست از handlerهاست. Mediator هماهنگی را متمرکز و Iterator پروتکل پیمایش را جدا می‌کند. State رفتار وابسته به وضعیت و Template Method اسکلت الگوریتم با نقاط تغییر را بیان می‌کنند. Visitor عملیات تازه روی خانوادهٔ نوع‌ها را با trade-off تغییر نوع می‌افزاید؛ Memento snapshot لازم برای بازگردانی،Interpreter معنای یک زبان محدود را مدل می‌کند. این الگوها جای یک lambda،switch یا متد ساده را بدون نیاز واقعی نمی‌گیرند. ترتیب،خطا و عمر subscription باید با قرارداد رفتار سنجیده شوند،نه فقط با نمودار کلاس.",
'Func<int,int> normal=n=>n;Func<int,int> vip=n=>n/2;\nConsole.WriteLine(Apply(10,vip));\nstatic int Apply(int price,Func<int,int> strategy)=>strategy(price);', '5',
("برای دو سیاست تخفیف ساده چه پیاده‌سازی حداقلی می‌تواند کافی باشد؟", "Func یا interface کوچک Strategy", "یازده لایهٔ الگو برای هر شرط", "singleton mutable در همهٔ متدها", "رفتار جایگزین واقعی را می‌توان با delegate کوچک مدل کرد؛ تعداد الگوها هدف نیست."),
analogy("رفتار جایگزین", "جفت مرجع: Strategy به انتخاب الگوریتم. جفت دوم را با رابطهٔ «الگو به مسئولیت» بساز.", ["الگو به مسئولیت", "وراثت نوعی", "Observer", "اعلان تغییر به مشترک‌ها", "Builder", "قفل حافظه"], [[0,2,3]]),
"گردش سفارش Draft→Submitted→Cancelled را با State یا switch روشن مدل کن و دو Strategy قیمت بده. انتقال نامعتبر رد شود؛ مقایسه کن آیا class جدا برای هر State لازم است.",
'var order=new Order();order.Submit();order.Cancel();Console.WriteLine(order.State);\ntry {order.Submit();} catch(InvalidOperationException) {Console.WriteLine("invalid transition");}\nenum OrderState {Draft,Submitted,Cancelled}\nclass Order\n{public OrderState State {get;private set;}\npublic void Submit(){if(State!=OrderState.Draft)throw new InvalidOperationException();State=OrderState.Submitted;}\npublic void Cancel(){if(State!=OrderState.Submitted)throw new InvalidOperationException();State=OrderState.Cancelled;}}',
"Cancelled و invalid transition چاپ شود. دو Strategy مستقل تست و انتخاب switch یا State با پیچیدگی واقعی توجیه شود.")

unit(119,
"Generic Host چرخهٔ configuration،DI،logging و shutdown را در برنامهٔ غیروب هم مدیریت می‌کند. BackgroundService کار طولانی را با token توقف اجرا می‌کند و باید تمام taskهای زیرین را مالک باشد. singleton نباید scoped dependency را مستقیم capture کند؛ scope برای هر واحد کار ساخته و dispose یا async dispose شود. factory و keyed service انتخاب پیاده‌سازی را در composition root نگه می‌دارند. options validation خطای تنظیمات را زود و reload تغییرات مجاز را با قرارداد روشن اعمال می‌کند. lifetime diagnostics و ValidateScopes بعضی خطاهای عمر را آشکار می‌کنند،نه همهٔ اشتراک‌های mutable را. توقف موفق یعنی worker و منابع تمام شده‌اند،نه فقط صدور Cancel.",
'using var scope=new Scope();Console.WriteLine(scope.Value);\nclass Scope:IDisposable {public int Value=>3;public void Dispose(){}}', '3',
("singleton worker برای سرویس scoped هر کار چه کند؟", "scope همان کار را بسازد و پس از پایان آزاد کند.", "سرویس scoped را برای همیشه در field نگه دارد.", "تمام سرویس‌ها را بدون بررسی singleton کند.", "scope مالک عمر کوتاه را مشخص می‌کند؛ نگهداری آن در singleton captive dependency می‌سازد."),
mission("عمر worker", "هر پیام یک واحد کار scoped دارد و worker باید قابل توقف باشد.", [("پیام تازه رسیده است.","ساخت scope همان واحد کار","گرفتن scoped از root و نگهداری دائمی"),("درخواست توقف رسیده است.","ارسال token و await کارهای فعال","قطع بی‌خبر و رهاکردن task"),("کار فعال تمام یا لغو شده است.","await cleanup و dispose scope","استفادهٔ دوباره از سرویس disposed")]),
"BackgroundService با Channel bounded بساز. برای هر پیام async scope بگیر؛ توقف token را منتقل و taskها را await کند. ValidateScopes خطای capture scoped در singleton را در تست آشکار کند.",
'using Microsoft.Extensions.DependencyInjection;\nvar services=new ServiceCollection();services.AddScoped<Work>();\nawait using var provider=services.BuildServiceProvider(new ServiceProviderOptions {ValidateScopes=true});\nawait using(var scope=provider.CreateAsyncScope()) Console.WriteLine(scope.ServiceProvider.GetRequiredService<Work>().Run());\nclass Work {public int Run()=>4;}',
"4 چاپ شود. worker نهایی scope را در field نگه ندارد؛ shutdown،خطا و لغو با وابستگی fake و بدون sleep تست شوند.")

unit(120,
"معماری مرز مسئولیت و جهت وابستگی را روشن می‌کند. لایه‌بندی یا Clean Architecture سیاست دامنه را از جزئیات UI و ذخیره جدا می‌کند؛ Vertical Slice تغییر را حول قابلیت گروه می‌کند و می‌تواند با مرز دامنه ترکیب شود. CQS فرمان و پرسش را جدا می‌بیند؛ CQRS مدل‌های خواندن و نوشتن جدا می‌خواهد و برای هر CRUD ساده لازم نیست. Repository و UnitOfWork فقط وقتی قرارداد و مرز تراکنش لازم را بیان کنند ارزش دارند؛ wrapper بی‌معنا روی هر API هدف نیست. مدل دامنه invariant را نگه می‌دارد. تراکنش باید واحد سازگار عملیات را پوشش دهد و side effect بیرونی نیاز به قرارداد تحویل جدا دارد. توزیع زودهنگام هزینهٔ شبکه و شکست جزئی می‌سازد.",
'Console.WriteLine(new Checkout(new MemoryPrices()).Total(2));\ninterface IPrices {int UnitPrice();}\nclass MemoryPrices:IPrices {public int UnitPrice()=>3;}\nclass Checkout(IPrices prices) {public int Total(int quantity)=>prices.UnitPrice()*quantity;}', '6',
("برای برنامهٔ کوچک تک‌فرایندی،microservice چه زمانی توجیه می‌خواهد؟", "وقتی نیاز واقعی مرز تحویل،مقیاس یا مالکیت هزینه‌اش را توجیه کند.", "همیشه صرفاً به دلیل مدرن بودن", "فقط چون نام فصل معماری است", "توزیع مرز شکست و عملیات می‌افزاید؛ انتخاب باید از نیاز و trade-off بیاید."),
argument("جهت وابستگی", "قانون محاسبه باید بدون PostgreSQL و UI قابل تست باشد.", ["دامنه به قرارداد لازم وابسته بماند", "دامنه مستقیماً به UI و دیتابیس وابسته شود", "تست منطق با fake مستقل اجرا می‌شود", "دیتابیس یک نام کوتاه دارد", "جزئیات زیرساخت نباید پیش‌نیاز اجرای قانون باشند", "هر متد یک microservice می‌خواهد"], [[0,2,4]]),
"برای سفارش دو چیدمان layered و vertical slice مقایسه کن. یک پیاده‌سازی کوچک با دامنهٔ مستقل و مرز تراکنش مشخص تحویل بده؛ تست منطق بدون دیتابیس باشد.",
'var service=new Checkout(new FixedPrices(3));if(service.Total(2)!=6)throw new Exception("domain");Console.WriteLine("passed");\ninterface IPrices {decimal UnitPrice();}\nclass FixedPrices(decimal price):IPrices {public decimal UnitPrice()=>price;}\nclass Checkout(IPrices prices)\n{public decimal Total(int quantity){if(quantity<=0)throw new ArgumentOutOfRangeException(nameof(quantity));decimal price=prices.UnitPrice();if(price<0)throw new InvalidOperationException("price");return checked(quantity*price);}}',
"passed چاپ شود و تست تعداد صفر و قیمت منفی وجود داشته باشد. جهت وابستگی و مرز commit واقعی مستند باشد؛ الگوی اضافه بدون مسئله ساخته نشود.")

unit(121,
"IObservable<T> داده را با OnNext و پایان را با OnCompleted یا OnError به IObserver می‌رساند؛ IDisposable برگشتی Subscribe عمر اشتراک را کنترل می‌کند. hot source مستقل از هر مشترک جریان دارد و cold معمولاً برای هر اشتراک تولید جدا دارد؛ قرارداد واقعی منبع باید خوانده شود. event برای اعلان ساده،async stream برای تقاضای awaitشونده و Channel برای صف producer/consumer با backpressure مناسب‌اند. Observable به‌تنهایی backpressure عمومی تضمین نمی‌کند. System.Reactive عملگرهای ترکیب می‌دهد و وابستگی اختیاری متناسب با نیاز است؛ weak event هم جای مالکیت روشن تمام منابع را نمی‌گیرد. خطا و unsubscribe باید تست شوند تا subscriber ناخواسته زنده نماند.",
'IObservable<int> source=new OneValue();using var subscription=source.Subscribe(new Printer());\nclass OneValue:IObservable<int> {public IDisposable Subscribe(IObserver<int> observer){observer.OnNext(3);observer.OnCompleted();return new Subscription();}}\nclass Subscription:IDisposable {public void Dispose(){}}\nclass Printer:IObserver<int> {public void OnNext(int n)=>Console.WriteLine(n);public void OnCompleted()=>Console.WriteLine("done");public void OnError(Exception e)=>Console.WriteLine("error");}', '3\ndone',
("Observable به‌تنهایی چه تضمینی ندارد؟", "backpressure و محدودیت صف برای هر producer", "قرارداد OnNext برای داده", "امکان پایان با OnCompleted یا OnError", "کنترل فشار تولید باید در قرارداد source یا لایهٔ اضافه طراحی شود؛ صرف Subscribe سقف حافظه نمی‌سازد."),
activity("deduction","انتخاب مدل جریان","از سرنخ‌ها هر نیاز را به یک مدل متفاوت وصل کن.", ["event","IAsyncEnumerable","Channel"], ["0:0","1:1","2:2"], Rows=["اعلان سادهٔ تغییر","مصرف تدریجی با await foreach","صف bounded دو سمت مستقل"], Clues=["اعلان ساده در این سناریو صف مستقل ندارد.","مصرف‌کنندهٔ تدریجی خودش MoveNextAsync می‌خواهد.","مدل صف باید ظرفیت و completion داشته باشد."], Game={}, Solution="اعلان: event؛ مصرف تقاضامحور: IAsyncEnumerable؛ صف bounded: Channel."),
"یک منبع را با event و async stream مقایسه کن. نمونهٔ Observable کوچک باید Dispose اشتراک و تکمیل/خطا را رعایت کند؛ مشترک جداشده دیگر OnNext نگیرد.",
'var source=new Source();var observer=new Counter();var subscription=source.Subscribe(observer);source.Emit(1);subscription.Dispose();source.Emit(2);Console.WriteLine(observer.Count);\nclass Counter:IObserver<int> {public int Count;public void OnNext(int value)=>Count++;public void OnError(Exception error){}public void OnCompleted(){}}\nclass Source:IObservable<int>\n{readonly List<IObserver<int>> observers=[];public IDisposable Subscribe(IObserver<int> observer){observers.Add(observer);return new Subscription(()=>observers.Remove(observer));}\npublic void Emit(int value){foreach(var observer in observers.ToArray())observer.OnNext(value);}}\nsealed class Subscription(Action remove):IDisposable {bool disposed;public void Dispose(){if(disposed)return;disposed=true;remove();}}',
"1 چاپ شود. نمونه تک‌thread است؛ نسخهٔ همزمان باید policy جدا داشته باشد. تست terminal event و عدم ارسال پس از پایان در پیاده‌سازی نهایی وجود داشته باشد.")

unit(122,
"تحویل قابل تکرار از checkout پاک و دستورهای معلوم شروع می‌شود. CI باید restore،build،test،format check،pack و publish لازم را با نسخهٔ SDK و ورودی مشخص انجام دهد. خروجی قابل انتشار باید واقعاً اجرا و با sample consumer بررسی شود؛ سبز بودن build به‌تنهایی رفتار را ثابت نمی‌کند. نسخه و release note تغییر قرارداد و مسیر مهاجرت را روشن می‌کنند. بررسی وابستگی،گزارش benchmark و trace فقط وقتی با روش و محیط واقعی همراه باشند شاهدند. code review باید خطا،عمر منبع،سازگاری و خوانایی را ببیند. artifact،دستور اجرا و محدودیت پلتفرم کنار هم لازم‌اند؛ هیچ درصد کارایی یا امنیتی بدون مدرک گزارش نشود.",
'string[] steps={"restore","build","test","pack","publish"};Console.WriteLine(steps[2]);', 'test',
("پس از publish چه بررسی‌ای برای تحویل لازم است؟", "اجرای artifact هدف با سناریوی مشخص", "اعلام موفقیت فقط از وجود فایل", "حذف warningها از گزارش بدون رسیدگی", "خروجی publish می‌تواند در محیط هدف مشکل runtime یا محتوا داشته باشد؛ smoke test artifact لازم است."),
constraints("گیت تحویل", "format و test می‌توانند پس از build مستقل انجام شوند؛ انتشار پس از هر دو بررسی است.", ["restore locked", "build", "test", "format check", "pack/publish", "اجرای artifact و ثبت شواهد"], [[0,1],[1,2],[1,3],[2,4],[3,4],[4,5]]),
"pipeline CI برای کتابخانه و مصرف‌کننده بساز؛ در محیط تازه restore locked،build،test،format،pack و publish اجرا شوند. artifact را با دادهٔ smoke تست کن و release note دقیق بنویس.",
'public static class Smoke\n{\n    public static int Run() {int result=checked(2+3);if(result!=5)throw new Exception("artifact contract");return result;}\n}\n',
"کتابخانه build و مصرف‌کننده Smoke.Run() را با انتظار 5 اجرا کند. workflow واقعی و log هر گیت همراه artifact باشد؛ snippet کتابخانه جای pipeline اجراشده نیست.")

unit(123,
"پروژهٔ نهایی توانایی تغییر و دفاع از تصمیم را می‌سنجد،نه تعداد keywordها. ابزار پردازش داده یا worker باید validation،JSON/I/O،async،لغو و محدودیت همزمانی داشته باشد. مدل داده و equality با معنا،خطا و ownership با قرارداد و وابستگی با مرز قابل تست انتخاب شوند. حالت خالی،خراب،بزرگ و توقف میانهٔ کار باید مشاهده شوند. آزمون خودکار،اجرای واقعی،گزارش کارایی و دستور بازتولید شواهد اصلی‌اند؛ ثبت شخصی تکمیل جای آن‌ها نیست. در مرور مصاحبه،علت تصمیم و تغییر یک شرط مرزی را توضیح بده. اگر قابلیت پیشرفته نیاز واقعی ندارد،حذف آن تصمیم حرفه‌ای معتبر است.",
'using System.Text.Json;\nint[] values=JsonSerializer.Deserialize<int[]>("[2,3,4]")!;Console.WriteLine(values.Where(n=>n>2).Sum());', '7',
("کدام شاهد به‌تنهایی تسلط عملی پروژهٔ نهایی را ثابت نمی‌کند؟", "فقط XP یا ثبت شخصی بدون کد و اجرای واقعی", "تست مستقل و خروجی واقعی قابل بازتولید", "توضیح و اصلاح یک خطای مرزی در کد خودت", "امتیاز ثبت فعالیت است؛ درستی و تسلط به اجرا،آزمون و توان تغییر نیاز دارد."),
budget("تحویل نهایی کافی", "پروژه باید دادهٔ معتبر،توقف سالم،آزمون و شواهد داشته باشد. هزینه‌های این معما واقعی نیستند.", ["validation و I/O امن", "لغو و مالکیت worker", "تست مرزی و fake", "دستور اجرا و benchmark واقعی", "قابلیت تزئینی بدون نیاز"], [1,1,1,1,5], [["داده"],["توقف"],["آزمون"],["شاهد"],[]], ["داده","توقف","آزمون","شاهد"], 4, [0,1,2,3]),
"ابزار پردازش JSON یا worker با فایل ورودی،خروجی مشخص و لغو بساز. صف و ورودی را محدود کن؛ تست خراب‌داده،توقف،خطای ذخیره و عدم از دست رفتن دادهٔ سالم بنویس. README اجرا،گزارش واقعی benchmark و دلیل معماری تحویل بده. نمونهٔ مرجع هستهٔ محاسبهٔ مستقل است؛ محصول نهایی باید I/O و shutdown آزموده را هم داشته باشد.",
'using System.Text.Json;\nConsole.WriteLine(await ProcessAsync("[2,3,4]",CancellationToken.None));\nstatic async Task<int> ProcessAsync(string json,CancellationToken token)\n{\n    token.ThrowIfCancellationRequested();if(json.Length>10000)throw new ArgumentException("too large");\n    int[] values=JsonSerializer.Deserialize<int[]>(json)??throw new InvalidDataException("null");\n    if(values.Length>1000||values.Any(n=>n<0))throw new InvalidDataException("data");\n    await Task.CompletedTask;token.ThrowIfCancellationRequested();return values.Where(n=>n>2).Sum();\n}',
"هسته 7 بدهد و null،منفی،طول زیاد و token لغوشده رد شوند. تحویل نهایی شامل I/O امن،shutdown،تست،artifact اجراشده و شواهد کارایی باشد؛ XP مدرک صحت نیست.")
